                    val = float(args[0])
                    if val <= 0:
                        raise CalculatorError("DOMAIN_ERROR", "Logarithm input must be strictly positive.")
                    res = math.log(val)
                elif func_name == "log10":
                    val = float(args[0])
                    if val <= 0:
                        raise CalculatorError("DOMAIN_ERROR", "Logarithm input must be strictly positive.")
                    res = math.log10(val)
