/* Scientific Calculator Styles & Extended State Layouts */
.app-layout-wrapper {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: center;
  gap: 20px;
  max-width: 900px;
  width: 100%;
  box-sizing: border-box;
}

@media (max-width: 800px) {
  .app-layout-wrapper {
    flex-direction: column;
    align-items: center;
  }
}

/* Extended Container sizing for desktop side-by-side buttons */
.calculator-container.scientific-active {
  max-width: 520px;
}

/* Row for badges, unit triggers, and drawer switches */
.calculator-controls-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #1a202c;
  padding: 8px 12px;
  border-radius: 8px;
  box-sizing: border-box;
}

.control-badge-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.badge-m {
  background: #ecc94b;
  color: #1a202c;
  font-weight: bold;
  font-size: 0.75rem;
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.badge-angle {
  background: #4299e1;
  color: #fff;
  font-weight: 600;
  font-size: 0.75rem;
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
}

.btn-control-toggle {
  background: #4a5568;
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.btn-control-toggle:hover {
  background: #718096;
}

.btn-control-toggle.active {
  background: #319795;
}

/* Collapsible Scientific Buttons Keypad Grid */
.scientific-grid-container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  background: rgba(26, 32, 44, 0.4);
  padding: 12px;
  border-radius: 12px;
  box-sizing: border-box;
  animation: slideDown 0.25s ease-out;
}

.btn-scientific {
  background: #2c5282;
  color: #fff;
}

.btn-scientific:hover {
  background: #3182ce;
}

.btn-memory {
  background: #2d3748;
  color: #ecc94b;
  border: 1px solid #ecc94b;
}

.btn-memory:hover {
  background: #ecc94b;
  color: #2d3748;
}

/* History drawer slideout panel */
.history-drawer-panel {
  width: 100%;
  max-width: 320px;
  background: #2d3748;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  padding: 20px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 580px;
  animation: slideIn 0.25s ease-out;
}

@media (max-width: 800px) {
  .history-drawer-panel {
    max-width: 380px;
    max-height: 250px;
  }
}

.history-drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #4a5568;
  padding-bottom: 8px;
}

.history-drawer-title {
  color: #fff;
  font-size: 1.1rem;
  font-weight: 600;
  margin: 0;
}

.btn-clear-history {
  background: #e53e3e;
  color: #fff;
  border: none;
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.btn-clear-history:hover {
  background: #c53030;
}

.history-items-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
  flex: 1;
  padding-right: 4px;
}

.history-empty-text {
  color: #a0aec0;
  font-size: 0.9rem;
  text-align: center;
  padding: 20px 0;
  margin: 0;
}

.history-item-row {
  background: #1a202c;
  border-radius: 8px;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: flex-end;
  cursor: pointer;
  border: 1px solid transparent;
  transition: border-color 0.15s, background 0.15s;
}

.history-item-row:hover {
  border-color: #4df899;
  background: #252f3f;
}

.history-item-expr {
  color: #a0aec0;
  font-size: 0.8rem;
  word-break: break-all;
  width: 100%;
  text-align: left;
}

.history-item-res {
  color: #4df899;
  font-weight: bold;
  font-size: 1rem;
  word-break: break-all;
  width: 100%;
  text-align: right;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideIn {
  from { opacity: 0; transform: translateX(10px); }
  to { opacity: 1; transform: translateX(0); }
}

