    setExpression('');
    setResult('');
    setError('');
  };

  const handleBackspace = () => {
    setError('');
    setExpression((prev) => (prev.length > 0 ? prev.slice(0, -1) : ''));
  };

  const handleEvaluate = async () => {
    if (!expression) return;
    setLoading(true);
    setError('');
